/**
 * #vi-prop's kill metric: of the rederives that cleared a stale mark, the share with no
 * change to the card's text. A high share says the marks are noise. The threshold, window,
 * and minimum sample are read from the card's own kill criterion, so they live in one place.
 */
function clearedHtml(G, ids) {
  const k = G.byId.get('vi-prop')?.kill?.find((c) => c.form === 'metric')
  const threshold = parseFloat(k?.threshold?.replace(/[^\d.]/g, '') ?? '80')
  const days = parseInt(k?.window ?? '30', 10)
  const minSample = k?.minSample ?? 30
  const since = Date.now() - days * 864e5
  const rows = (flows.rederives ?? []).filter((r) => ids.has(r.id) && Date.parse(r.at) >= since)
  const same = rows.filter((r) => !r.changed)
  const pct = (n, of) => (of ? Math.round((n / of) * 100) : 0)
  const share = pct(same.length, rows.length)
  const state = rows.length < minSample ? 'thin' : share > threshold ? 'fires' : 'holds'
  const chip = { thin: 'not enough data', fires: 'fires', holds: 'holds' }[state]
  const color = { thin: 'paused', fires: 'stale', holds: 'decided' }[state]
  const born = same.filter((r) => r.bornAfter).length
  // The bar is the whole sample. Its two "unchanged" parts sum to the share the threshold is
  // checked against, so the fill edge and the threshold mark compare directly.
  const w = (n) => (rows.length ? (n / rows.length) * 100 : 0)
  const seg = (n, cls, title) => (n ? `<i class="${cls}" style="width:${w(n)}%" title="${esc(title)}"></i>` : '')
  return `<div class="kill-gauge" style="--c:var(--${color})">
      <div class="kg-head">
        <span class="kg-chip">${chip}</span>
        <span class="kg-share"><b>${share}%</b> left the text unchanged</span>
        <span class="kg-crit">revisit <button class="flow-open" data-open="vi-prop">#vi-prop</button> above <b>${threshold}%</b></span>
      </div>
      <div class="kg-track">
        ${seg(born, 'kg-born', `${born} unchanged, card born after the reopen`)}${seg(same.length - born, 'kg-same', `${same.length - born} unchanged, other`)}${seg(rows.length - same.length, 'kg-changed', `${rows.length - same.length} text changed`)}
        <span class="kg-mark" style="left:${threshold}%"><span>${threshold}%</span></span>
      </div>
      <div class="kg-legend">
        <span><i class="kg-born"></i>${born} unchanged, card born after the reopen</span>
        <span><i class="kg-same"></i>${same.length - born} unchanged, other</span>
        <span><i class="kg-changed"></i>${rows.length - same.length} text changed</span>
        <span class="kg-sample ${state === 'thin' ? 'short' : ''}">${rows.length} cleared in ${days}d · minimum ${minSample}</span>
      </div>
    </div>`
}

